import os, re, json, httpx
BASE='http://127.0.0.150'
try:
    aegispt_emit_finding
except NameError:
    def aegispt_emit_finding(**kwargs):
        print(json.dumps(kwargs))

def first_env(*names):
    for name in names:
        value = os.getenv(name)
        if value:
            return value
    return None

def login_client():
    client = httpx.Client(base_url=BASE, follow_redirects=True, timeout=10.0)
    cookies_json = first_env('AUTH_COOKIES_JSON', 'COOKIES_JSON')
    if cookies_json:
        try:
            client.cookies.update(json.loads(cookies_json))
        except Exception:
            pass
    phpsessid = first_env('PHPSESSID', 'SESSIONID', 'SESSION_COOKIE')
    if phpsessid:
        client.cookies.set('PHPSESSID', phpsessid, domain='127.0.0.150', path='/')
    if not client.cookies:
        username = first_env('LOW_PRIV_USERNAME', 'VAULT_USERNAME', 'USERNAME', 'LOGIN_USERNAME')
        password = first_env('LOW_PRIV_PASSWORD', 'VAULT_PASSWORD', 'PASSWORD', 'LOGIN_PASSWORD')
        if not (username and password):
            raise SystemExit('No authenticated low-priv context from vault was supplied.')
        client.post('/index.php', data={'username': username, 'password': password})
    return client

with login_client() as client:
    resp = client.get('/server-status')
    markers = [m for m in ['Apache Server Status', 'Server Version', 'Current Time', 'Scoreboard'] if m.lower() in resp.text.lower()]
    if resp.status_code == 200 and markers:
        lines = []
        for line in resp.text.splitlines():
            if any(m.lower() in line.lower() for m in markers):
                cleaned = re.sub(r'<[^>]+>', ' ', line).strip()
                if cleaned:
                    lines.append(cleaned)
        excerpt = ' | '.join(lines)[:500]
        aegispt_emit_finding(evidence_url=BASE + '/server-status', evidence_excerpt='Authenticated low-priv session reached mod_status. ' + excerpt)
    else:
        print(json.dumps({'status_code': resp.status_code, 'body_snippet': re.sub(r'<[^>]+>', ' ', resp.text)[:200]}))
